<template>
  <div class="marker-icon-picker" id="markerIconPicker">
    <div class="icon-list" v-if="mode === 'vr'">
      <div
        class="icon-item"
        v-for="(item, index) in markerIconItems"
        :key="index"
        @click="chooseIcon(item)"
        :class="item.key === currentKey ? 'actived' : ''"
      >
        <!-- <img :src="item.url" :alt="item.key" :class="{'plus-icon-img': item.key.indexOf('v2_') >= 0}" /> -->
        <img
          :src="item.url"
          :alt="item.key"
          v-if="item.key.indexOf('v2_') < 0"
        />
        <div
          class="plus-icon-img"
          :style="{
            backgroundImage: `url(${item.url})`,
            backgroundPositionX: 0,
            backgroundPositionY: 0,
            backgroundSize: '100%',
            height: '100%',
          }"
          v-else
        ></div>
      </div>
    </div>
    <div class="icon-list" v-if="mode === 'element'">
      <div
        class="icon-item ele-icon-item"
        v-for="(item, index) in eleIcons"
        :key="index"
        @click="chooseEleIcon(item)"
        :class="item === currentKey ? 'actived' : ''"
      >
        <i :class="item"></i>
      </div>
    </div>
  </div>
</template>

<script>
import eleIcons from '@/config/icons'
export default {
  name: 'MarkerIconPicker',
  data() {
    return {
      currentKey: '',
      eleIcons: eleIcons,
    }
  },
  props: {
    value: String,
    mode: {
      type: String,
      default: 'vr',
    },
  },
  mounted() {
    this.currentKey = this.value
    this.setScrollTop()
  },
  computed: {
    markerIconItems() {
      const defaultIconItems = [
        {
          key: 'front_gif',
          url: require('../assets/default/icons/front_gif.png'),
        },
        {
          key: 'left_gif',
          url: require('../assets/default/icons/left_gif.png'),
        },
        {
          key: 'bottom_gif',
          url: require('../assets/default/icons/bottom_gif.png'),
        },
        {
          key: 'right_gif',
          url: require('../assets/default/icons/right_gif.png'),
        },
        {
          key: 'left2_gif',
          url: require('../assets/default/icons/left2_gif.png'),
        },
        {
          key: 'right2_gif',
          url: require('../assets/default/icons/right2_gif.png'),
        },
        {
          key: 'dot_gif',
          url: require('../assets/default/icons/dot_gif.png'),
        },
        {
          key: 'zoom_gif',
          url: require('../assets/default/icons/zoom_gif.png'),
        },
        {
          key: 'plus_gif',
          url: require('../assets/default/icons/plus_gif.png'),
        },
      ]
      for (let index = 1; index <= 34; index++) {
        defaultIconItems.push({
          key: `v2_${index}_gif`,
          url: require(`../assets/default/icons/${index}_animate.png`),
        })
      }

      const noGifIconItems = [
        {
          key: 'front',
          url: require('../assets/default/icons/front.png'),
        },
        {
          key: 'left',
          url: require('../assets/default/icons/left.png'),
        },
        {
          key: 'bottom',
          url: require('../assets/default/icons/bottom.png'),
        },
        {
          key: 'right',
          url: require('../assets/default/icons/right.png'),
        },
        {
          key: 'left2',
          url: require('../assets/default/icons/left2.png'),
        },
        {
          key: 'right2',
          url: require('../assets/default/icons/right2.png'),
        },
        {
          key: 'dot',
          url: require('../assets/default/icons/dot.png'),
        },
        {
          key: 'zoom',
          url: require('../assets/default/icons/zoom.png'),
        },
        {
          key: 'plus',
          url: require('../assets/default/icons/plus.png'),
        },
        {
          key: 'point1',
          url: require('../assets/default/icons/point1.png'),
        },
        {
          key: 'point2',
          url: require('../assets/default/icons/point2.png'),
        },
        {
          key: 'point3',
          url: require('../assets/default/icons/point3.png'),
        },
        {
          key: 'camera_3d',
          url: require('../assets/default/icons/camera_3d.png'),
        },
        {
          key: 'camera2_3d',
          url: require('../assets/default/icons/camera2_3d.png'),
        },
        {
          key: 'weather',
          url: require('../assets/default/icons/weather.png'),
        },
        {
          key: 'soil',
          url: require('../assets/default/icons/soil.png'),
        },
        {
          key: 'pest',
          url: require('../assets/default/icons/pest.png'),
        },
        {
          key: 'smart',
          url: require('../assets/default/icons/smart.png'),
        }
      ]

      defaultIconItems.push(...noGifIconItems)

      return defaultIconItems
    },
  },
  methods: {
    changeKey(key) {
      this.currentKey = key
      this.setScrollTop()
      return this.markerIconItems.find((item) => item.key === key)
    },
    chooseIcon(item) {
      this.currentKey = item.key
      this.$emit('change', item.key)
    },
    chooseEleIcon(item) {
      this.currentKey = item
      this.$emit('change', item)
    },
    setScrollTop() {
      this.$nextTick(() => {
        const dom = document.getElementById('markerIconPicker')
        if (this.mode === 'vr') {
          const index =
            this.markerIconItems.findIndex(
              (item) => item.key === this.currentKey
            ) + 1
          const rows = Math.ceil(index / 4)
          const top = dom.scrollTop + rows * 50
          console.log('dom.scrollTop:', top)
          dom.scrollTo({ top: top, behavior: 'smooth' })
        } else if (this.mode === 'element') {
          const index =
            this.eleIcons.findIndex((item) => item === this.currentKey) + 1
          const rows = Math.ceil(index / 4)
          const top = dom.scrollTop + rows * 27
          console.log('dom.scrollTop:', top)
          dom.scrollTo({ top: top, behavior: 'smooth' })
        }
      })
    },
  },
}
</script>

