  padding-top: 10px;
  height: 170px;
  inset: 0px;
  overflow: scroll;
  //margin-right: -15px;
  margin-bottom: -15px;
  .icon-list {
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-orient: horizontal;
    -webkit-box-direction: normal;
    -ms-flex-flow: row wrap;
    flex-flow: row wrap;
    -webkit-box-pack: justify;
    -ms-flex-pack: justify;
    justify-content: flex-start;
    overflow-x: hidden;
    .icon-item {
      position: relative;
      width: 35px;
      height: 35px;
      margin: 0 2px 15px;
      cursor: pointer;
      &.ele-icon-item {
        width: 20px;
        height: 20px;
        margin: 0 2px 5px 2px;
        padding: 2px;
        text-align: center;
        &.actived {
          outline: unset;
          outline-offset: unset;
          border: 2px solid #67c23a;
        }
      }
      &.actived {
        outline: #67c23a solid 2px;
        outline-offset: -2px;
      }

      img {
        width: 100%;
        height: 100%;
        display: block;
      }
      .plus-icon-img {
        &::after {
          content: "GIF";
          display: block;
